export declare class GlideSysListControl {
  /**
   
   * Creates a new SysListControl instance.
   */
  constructor();
  /**
   
   * Creates a new SysListControl instance for the specified table.
   */
  constructor(tableName: string);

  /**
   
   * Returns the control ID for this list control.
   */
  getControlID(): string;

  /**
   
   * Returns the label for this list control.
   */
  getLabel(): string;

  /**
   
   * Returns true if the edit button should be omitted.
   */
  isOmitEditButton(): boolean;

  /**
   
   * Returns true if the new button should be omitted.
   */
  isOmitNewButton(): boolean;

  /**
   
   * Returns true if the new button should be omitted, without additional checks.
   */
  isOmitNewButtonWithoutChecks(): boolean;

  /**
   
   * Returns true if the list should be omitted when empty.
   */
  isOmitEmpty(): boolean;

  /**
   
   * Returns true if the header should be omitted when empty.
   */
  isOmitHeaderEmpty(): boolean;

  /**
   
   * Returns true if the omit script evaluates to true.
   */
  isOmitScript(): boolean;

  /**
   
   * Returns true if the omit header script evaluates to true.
   */
  isOmitHeaderScript(): boolean;

  /**
   
   * Returns true if the filter should be omitted.
   */
  isOmitFilter(): boolean;

  /**
   
   * Returns true if links should be omitted.
   */
  isOmitLinks(): boolean;

  /**
   
   * Returns true if labels should be shown on each row.
   */
  isShowLabelsOnRow(): boolean;

  /**
   
   * Returns the search method for this list control.
   */
  getSearchMethod(): string;

  /**
   
   * Returns the mode for this list control.
   */
  getMode(): string;

  /**
   
   * Returns the list control ID (alias for getControlID).
   */
  getListControlID(): string;

  /**
   
   * Returns true if the list should not automatically try to link the first non-reference column to the underlying record.
   */
  shouldOmitDrilldownLink(): boolean;

  /**
   
   * Returns true if this list is hierarchical.
   */
  isHierarchicalLists(): boolean;

  /**
   
   * Returns true if a row can be inserted in list edit mode.
   */
  getListEditInsertRow(): boolean;

  /**
   
   * Returns the default filter associated with the control.
   */
  getEditDefaultFilter(): string;

  /**
   
   * Returns the list edit type for this control.
   */
  getListEditType(): string;

  /**
   
   * Returns the list edit reference qualifier tag.
   */
  getListEditRefQualTag(): string;

  /**
   
   * Returns a cached SysListControl for the specified table and related list.
   */
  static getListControl(
    tableName: string,
    relatedList: string
  ): GlideSysListControl;
}
